ALTER TABLE bookings ADD COLUMN revision INTEGER NOT NULL DEFAULT 0;
ALTER TABLE bookings ADD COLUMN adjustment_amount NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK(adjustment_amount>=0);
CREATE TABLE booking_changes (id BIGSERIAL PRIMARY KEY, booking_id BIGINT NOT NULL REFERENCES bookings, payload VARCHAR(20000) NOT NULL, revision INTEGER NOT NULL, status VARCHAR(255) NOT NULL CHECK(status IN ('PENDING','SUCCESS','FAILED','CANCELLED')), amount NUMERIC(14,2) NOT NULL CHECK(amount>=0), fee NUMERIC(14,2) NOT NULL CHECK(fee>=0), target_amount NUMERIC(14,2) NOT NULL CHECK(target_amount>=0), created_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL, request_key UUID UNIQUE);
CREATE INDEX idx_changes_booking ON booking_changes(booking_id,id);
CREATE TABLE refund_requests (id BIGSERIAL PRIMARY KEY, booking_id BIGINT NOT NULL UNIQUE REFERENCES bookings, status VARCHAR(255) NOT NULL CHECK(status IN ('REQUESTED','APPROVED','REJECTED','COMPLETED')), reason VARCHAR(2000) NOT NULL, staff_note VARCHAR(2000), amount NUMERIC(14,2) NOT NULL CHECK(amount>=0), fee NUMERIC(14,2) NOT NULL CHECK(fee>=0), created_at TIMESTAMPTZ NOT NULL, completed_at TIMESTAMPTZ);
CREATE TABLE change_payments (id BIGSERIAL PRIMARY KEY, change_id BIGINT NOT NULL REFERENCES booking_changes, request_key UUID UNIQUE NOT NULL, status VARCHAR(255) NOT NULL, amount NUMERIC(14,2) NOT NULL CHECK(amount>=0), created_at TIMESTAMPTZ NOT NULL);
